using System; using System.IO; using System.Linq; namespace CollegePortal.Gateway { public class NonceStore { private readonly string _path; private readonly int _windowSeconds; private readonly object _lock=new object(); public NonceStore(string path,int windowSeconds){ _path=path; _windowSeconds=windowSeconds; Directory.CreateDirectory(Path.GetDirectoryName(path)); if(!File.Exists(path)) File.WriteAllText(path,""); } public bool TryUse(string nonce,DateTime timestamp){ lock(_lock){ var now=DateTime.UtcNow; var rows=File.ReadAllLines(_path).Select(Parse).Where(x=>x.HasValue&&(now-x.Value.Time).TotalSeconds<=_windowSeconds).Select(x=>x.Value).ToList(); if(rows.Any(x=>x.Nonce==nonce)) return false; rows.Add(new Entry{Nonce=nonce,Time=timestamp.ToUniversalTime()}); File.WriteAllLines(_path,rows.Select(x=>x.Time.ToString("O")+" "+x.Nonce)); return true; }} private static Entry? Parse(string line){ var idx=line.IndexOf(' '); DateTime time; if(idx<=0||!DateTime.TryParse(line.Substring(0,idx),out time)) return null; return new Entry{Time=time.ToUniversalTime(),Nonce=line.Substring(idx+1)}; } private struct Entry{ public string Nonce; public DateTime Time; } }}
